%% Figure 3: penetration-level statistics for dioptic vs. dichoptic coherence
% Run after fig3abcd_coherence.m, OR select the .mat cache generated by
% fig3abcd_coherence_withCache.m when prompted.
%
% Penetrations are the independent observations (as in the original NHP
% analysis convention). Electrode pairs are pooled WITHIN each penetration.
% Requires MATLAB Statistics and Machine Learning Toolbox (ttest, fitrm,
% ranova). Does not recompute mscohere.

%% Retrieve stored coherence (15 x 15 x 2 conditions x penetrations)
if ~exist('averageCoherenceMatrix_diopDichop','var')
    [cacheName,cacheFolder] = uigetfile('*.mat', ...
        'Select fig3_coherence_perPenetration.mat');
    if isequal(cacheName,0)
        error('No coherence matrix in workspace, and no cache selected.');
    end
    cache = load(fullfile(cacheFolder,cacheName), ...
        'averageCoherenceMatrix_diopDichop');
    averageCoherenceMatrix_diopDichop = ...
        cache.averageCoherenceMatrix_diopDichop;
    outputDir = cacheFolder;
elseif exist('plotDir','var') && isfolder(plotDir)
    outputDir = plotDir;
else
    outputDir = pwd;
end
if ~exist('outputDir','var') || ~isfolder(outputDir)
    outputDir = pwd;
end

C = averageCoherenceMatrix_diopDichop;
assert(ndims(C)==4 && size(C,1)==15 && size(C,2)==15 && size(C,3)==2, ...
    'Expected a 15 x 15 x 2 x N coherence matrix.');

%% One dioptic-minus-dichoptic value per compartment boundary per penetration
boundaryNames = {'G-S','I-S','I-G'};
nPenTotal = size(C,4);
penetrationDifferences = nan(nPenTotal,3);
for k = 1:nPenTotal
    % Condition 1 = dioptic; condition 2 = dichoptic
    differenceMatrix = C(:,:,1,k) - C(:,:,2,k);
    blocks = {differenceMatrix(6:10,1:5), ...   % granular - supragranular
              differenceMatrix(11:15,1:5), ...  % infragranular - supragranular
              differenceMatrix(11:15,6:10)};   % infragranular - granular
    for b = 1:3
        values = blocks{b}(:);
        values = values(isfinite(values));
        if ~isempty(values)
            penetrationDifferences(k,b) = mean(values);
        end
    end
end

% Complete cases ensure that all repeated-measures tests use same penetrations.
valid = all(isfinite(penetrationDifferences),2);
D = penetrationDifferences(valid,:);
penetrationIDs = find(valid);
n = size(D,1);
assert(n>=3,'Fewer than three penetrations have all three valid boundaries.');
fprintf('\nFIGURE 3 PENETRATION-LEVEL ANALYSIS\n');
fprintf('Valid penetrations: %d / %d\n',n,nPenTotal);
fprintf('Contrast: dioptic minus dichoptic (positive = dioptic higher)\n');

%% Descriptive statistics and one-sample tests against zero
meanDifference = mean(D,1)';
sdDifference = std(D,0,1)';
semDifference = sdDifference ./ sqrt(n);
pZero = nan(3,1); tZero = nan(3,1); dfZero = nan(3,1);
ciLow = nan(3,1); ciHigh = nan(3,1);
for b = 1:3
    [~,pZero(b),CI,stats] = ttest(D(:,b),0);
    tZero(b) = stats.tstat;
    dfZero(b) = stats.df;
    ciLow(b) = CI(1);
    ciHigh(b) = CI(2);
end
pZeroHolm = holm_adjust(pZero);
boundarySummary = table(boundaryNames',repmat(n,3,1),meanDifference, ...
    sdDifference,semDifference,ciLow,ciHigh,tZero,dfZero,pZero,pZeroHolm, ...
    'VariableNames',{'Boundary','N','MeanDifference','SD','SEM', ...
    'CI95Low','CI95High','t','df','pUncorrected','pHolm'});
disp('Penetration-level coherence differences against zero (Holm across 3 boundaries):');
disp(boundarySummary);

%% Repeated-measures ANOVA: do the 3 boundaries differ?
T = array2table(D,'VariableNames',{'GS','IS','IG'});
within = table(categorical({'GS';'IS';'IG'}),'VariableNames',{'Boundary'});
rm = fitrm(T,'GS-IG ~ 1','WithinDesign',within);
rmResults = ranova(rm,'WithinModel','Boundary');
disp('Repeated-measures ANOVA across boundaries:');
disp(rmResults);
fprintf('For inference, report the Greenhouse-Geisser adjusted p if needed.\n');

%% Post-hoc paired tests between boundaries (Holm across 3 contrasts)
pairIDs = [1 2;1 3;2 3];
pBetween = nan(3,1); tBetween = nan(3,1); dfBetween = nan(3,1);
meanContrast = nan(3,1); contrastNames = cell(3,1);
for q = 1:3
    i = pairIDs(q,1); j = pairIDs(q,2);
    contrastNames{q} = sprintf('%s minus %s',boundaryNames{i},boundaryNames{j});
    deltas = D(:,i)-D(:,j);
    meanContrast(q) = mean(deltas);
    [~,pBetween(q),~,st] = ttest(D(:,i),D(:,j));
    tBetween(q) = st.tstat;
    dfBetween(q) = st.df;
end
pBetweenHolm = holm_adjust(pBetween);
betweenSummary = table(contrastNames,meanContrast,tBetween,dfBetween, ...
    pBetween,pBetweenHolm,'VariableNames', ...
    {'Contrast','MeanDifference','t','df','pUncorrected','pHolm'});
disp('Paired boundary contrasts (Holm across 3 comparisons):');
disp(betweenSummary);

%% Save numeric outputs for review and manuscript reporting
perPenTable = array2table(D,'VariableNames',{'GS','IS','IG'});
perPenTable = addvars(perPenTable,penetrationIDs,'Before',1, ...
    'NewVariableNames','PenetrationIndex');
writetable(perPenTable,fullfile(outputDir,'fig3_penetration_values.csv'));
writetable(boundarySummary,fullfile(outputDir,'fig3_penetration_summary.csv'));
writetable(betweenSummary,fullfile(outputDir,'fig3_boundary_pairwise.csv'));
save(fullfile(outputDir,'fig3_penetration_statistics.mat'), ...
    'D','penetrationIDs','penetrationDifferences','boundarySummary', ...
    'betweenSummary','rmResults','valid');

%% Visualization: 1 line per penetration, with mean +/- SEM
f = figure('Color','w','Position',[250 250 650 470]);
hold on;
for k = 1:n
    plot(1:3,D(k,:),'-','Color',[0.76 0.76 0.76],'LineWidth',0.7);
    plot(1:3,D(k,:),'.','Color',[0.55 0.55 0.55],'MarkerSize',8);
end
errorbar(1:3,meanDifference,semDifference,'ko-', ...
    'LineWidth',2.0,'MarkerSize',7,'MarkerFaceColor','k','CapSize',10);
yline(0,'k:');
xlim([0.65 3.35]); xticks(1:3); xticklabels(boundaryNames);
xlabel('Interlaminar compartment pair');
ylabel('Mean coherence difference (dioptic - dichoptic)');
title(sprintf('Coherence change across penetrations (n = %d)',n));
box off; hold off;
exportgraphics(f,fullfile(outputDir,'fig3_penetration_level.png'),'Resolution',300);
savefig(f,fullfile(outputDir,'fig3_penetration_level.fig'));

%% Revised t-map: paired t tests across penetrations; BH-FDR over 105 pairs
% Exploratory spatial map. Diagonal self-comparisons are excluded.
% Only the lower triangle was computed by fig3abcd_coherence.m.
tMap = nan(15,15);
pMap = nan(15,15);
for row = 2:15
    for col = 1:(row-1)
        dio = squeeze(C(row,col,1,valid));
        dich = squeeze(C(row,col,2,valid));
        [~,pMap(row,col),~,st] = ttest(dio(:),dich(:));
        tMap(row,col) = st.tstat;
    end
end
pairP = pMap(tril(true(15),-1));
finitePairP = pairP(isfinite(pairP));
numTests = numel(finitePairP);
qFDR = 0.05;
if numTests > 0
    sortedP = sort(finitePairP);
    passing = find(sortedP <= ((1:numTests)'./numTests)*qFDR);
    if isempty(passing)
        pThreshold = 0;
    else
        pThreshold = sortedP(passing(end));
    end
else
    pThreshold = 0;
end
fdrMask = pMap <= pThreshold & isfinite(pMap);
fprintf('t-map: %d unique channel pairs tested; %d survive BH-FDR q=%.2f.\n', ...
    numTests,nnz(fdrMask),qFDR);

e = figure('Color','w','Position',[200 200 560 510]);
imagesc(tMap);
axis image;
cb = colorbar;
cb.Label.String = 'Paired t statistic (dioptic - dichoptic)';
finiteT = abs(tMap(isfinite(tMap)));
if ~isempty(finiteT) && max(finiteT)>0
    clim([-max(finiteT) max(finiteT)]);
end
colormap(parula);
hold on;
if any(fdrMask(:))
    contour(double(fdrMask),[0.5 0.5],'k','LineWidth',1.3);
end
hold off;
xlabel('Channel'); ylabel('Channel');
title(sprintf('Across-penetration t-map; BH-FDR q = %.2f',qFDR));
exportgraphics(e,fullfile(outputDir,'fig3_tMap_FDR.png'),'Resolution',300);
savefig(e,fullfile(outputDir,'fig3_tMap_FDR.fig'));
save(fullfile(outputDir,'fig3_tMap_FDR.mat'),'tMap','pMap','fdrMask','pThreshold','qFDR','numTests');
fprintf('Saved Figure 3 results in: %s\n',outputDir);

%% Local helper: Holm familywise-error adjusted p-values
function pAdjusted = holm_adjust(pValues)
    pValues = pValues(:);
    pAdjusted = nan(size(pValues));
    isGood = isfinite(pValues);
    p = pValues(isGood);
    [ps,order] = sort(p);
    m = numel(ps);
    adjustedSorted = min(1,cummax((m-(1:m)'+1).*ps));
    adjusted = nan(m,1);
    adjusted(order) = adjustedSorted;
    pAdjusted(isGood) = adjusted;
end
